select jsonb_build_object('checked_at',clock_timestamp(),'expected',count(*),'exact',count(*)filter(where exact),'mismatches',coalesce(jsonb_agg(ref)filter(where not coalesce(exact,false)),'[]')) as verification from(select 'catalog_work_descriptions:65' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987147033 and t.language='nl')='{"text":"Een oud-medewerker opent het vuur in een populair restaurant in Los Angeles. Na de vele doden en gewonden lijkt de zaak duidelijk: getuigen zagen één schutter, die ook zichzelf heeft gedood. Rechercheur Peter Decker stuit echter op sporen die erop wijzen dat er meer dan één wapen is gebruikt. Zijn vragen brengen hem in een omgeving waarin geld en invloed de verhoudingen bepalen. Het verdere onderzoek maakt niet alleen het oorspronkelijke beeld onzeker, maar bedreigt ook zijn eigen reputatie en loopbaan.","work_id":987147033,"evidence":[{"note":"Retain Work5965 Serpent''s Tooth / Faye Kellerman; exact Dutch Het zoete gif ISBN 9789022525586 Paperback. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-033.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p180159275"],"reference":"work:5965","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-033.json","sources":["https://openlibrary.org/works/OL462947W","https://data.bibliotheken.nl/id/nbt/p180159275"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789022525586","status":"no_verified