evidence_url":"https://data.bibliotheken.nl/id/nbt/p238776484","review_batch":"nl-scale-20261102-048","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987304023}'::jsonb as exact union all select 'catalog_work_descriptions:71' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987147038 and t.language='nl')='{"text":"Een geschil over twee zomerhuizen brengt Bergljot opnieuw in aanraking met de familie die zij twintig jaar geleden achterliet. Haar ouders willen de huizen aan twee andere kinderen nalaten. Voor buitenstaanders lijkt het een ruzie over bezit en bevoordeling. Bergljot verbindt de keuze echter met een pijnlijke geschiedenis uit haar jeugd die volgens haar nog steeds wordt ontkend. Vigdis Hjorth onderzoekt hoe herinneringen en trauma een familieverhouding kunnen bepalen wanneer erkenning van het verleden belangrijker wordt dan de verdeling van een erfenis.","work_id":987147038,"evidence":[{"note":"Retain Work6018 Arv og miljø / Vigdis Hjorth; exact Dutch Zomerhuis ISBN 9789026340369 Paperback. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-033.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p416324762"],"reference":"work:6018","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-033.json","sources":["https://openlibrary.org/works/OL20863082W","https://data.bibliotheken.nl/id/nbt/p416324762"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset