utralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789026340369","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":14857943,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:35:36.998Z","editionKey":"/books/OL58372491M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987247039,"bound_title":"Zomerhuis","reviewed_at":"2026-11-03T09:35:36.993+00:00","bound_isbn13":"9789026340369","evidence_url":"https://data.bibliotheken.nl/id/nbt/p416324762","review_batch":"nl-scale-20261102-048","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987347018}'::jsonb as exact union all select 'catalog_work_descriptions:73' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987147039 and t.language='nl')='{"text":"De moord op projectontwikkelaar Guy Kaffey, zijn vrouw en enkele medewerkers brengt Peter Decker midden in een zaak rond grote rijkdom. De beveiligde woonomgeving doet vermoeden dat de daders hulp van binnenuit hadden. Familiebelangen, zakelijke vijanden en de achtergrond van het beveiligingspersoneel bieden verschillende richtingen voor het onderzoek. Rina lijkt veilig op afstand te blijven terwijl zij jurywerk doet, maar een ontmoeting met een tolk verbindt haar onverwacht met de zaak. Deckers professionele zoektocht krijgt daardoor ook thuis directe gevolgen.","work_id":987147039,"evidence":[{"note":"Retain Work6027 Blindman''s Bluff / Faye Kellerman; exact Dutch De blinde man ISBN 9789022555125 Paperback. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-033.json. No new Work, changed first-publication ye